<script setup>
import { ref, computed } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { useEvents } from '@/composables/useEvents'
import AppModal from '@/components/ui/AppModal.vue'
const route = useRoute(), router = useRouter()
const { userRegistrations, cancelRegistration, getEventById } = useEvents()
const eventId = computed(() => Number(route.params.id))
const activeTicket = computed(() => userRegistrations.value.find(r => r.eventId === eventId.value))
const event = computed(() => getEventById(eventId.value))
const isEventDone = computed(() => Boolean(event.value?.done))
const isCancelModalOpen = ref(false)
function handleConfirmCancel() { if (event.value && !event.value.done) { cancelRegistration(eventId.value); isCancelModalOpen.value = false; router.push('/browse/your-events') } }
</script>
<template><div class="ticket-receipt-page"><button class="btn-back" @click="router.push('/browse/your-events')">← Back to Your Events</button><article v-if="activeTicket && event" class="ticket-receipt-card"><header class="receipt-header"><div><span :class="['status-badge', isEventDone ? 'badge-concluded' : 'badge-confirmed']">{{ isEventDone ? 'CONCLUDED' : 'CONFIRMED PASS' }}</span><p class="receipt-meta-date">Registered on {{ new Date(activeTicket.registeredAt).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' }) }}</p></div><strong class="ref-code">{{ activeTicket.bookingCode }}</strong></header><section class="receipt-section"><h3 class="section-heading">EVENT DETAILS</h3><h1 class="event-title">{{ event.title }}</h1><div class="receipt-grid"><div><span class="item-label">Category</span><strong>{{ event.cat }}</strong></div><div><span class="item-label">Date & Time</span><strong>{{ event.date }}</strong></div><div><span class="item-label">Location</span><strong>{{ event.loc.replace(/^📍\s*/, '') }}</strong></div></div></section><section class="receipt-section"><h3 class="section-heading">ATTENDEE INFORMATION</h3><div class="receipt-grid attendee-grid"><div><span class="item-label">Full Name</span><strong>{{ activeTicket.fullName }}</strong></div><div><span class="item-label">Email Address</span><strong>{{ activeTicket.email }}</strong></div><div><span class="item-label">Phone Number</span><strong>{{ activeTicket.phone }}</strong></div><div><span class="item-label">Date of Birth</span><strong>{{ activeTicket.dob }}</strong></div></div></section><section class="receipt-section"><h3 class="section-heading">REASON FOR ATTENDING</h3><p class="reason-text">{{ activeTicket.reason }}</p></section><footer class="receipt-footer"><button class="btn-primary" @click="router.push('/browse/your-events')">Back to Your Events</button><button v-if="!isEventDone" class="btn-cancel-reg" @click="isCancelModalOpen=true">Cancel Registration</button><span v-else class="concluded-notice">This event has concluded. Attendance record is archived.</span></footer></article><div v-else class="notice-card"><h2>Ticket Not Found</h2><p>You do not have an active registration for this event, or it has been cancelled.</p><button class="btn-primary" @click="router.push('/browse/your-events')">View Your Events</button></div><AppModal :is-open="isCancelModalOpen" title="Cancel Registration?" message="Are you sure you want to cancel your registration for this event? This action will remove your ticket." confirm-text="Yes, Cancel Registration" @close="isCancelModalOpen=false" @confirm="handleConfirmCancel" /></div></template>
<style scoped>.ticket-receipt-page{max-width:850px;margin:auto;padding:32px 0}.btn-back{border:0;background:none;color:var(--text-muted);cursor:pointer;margin-bottom:22px}.ticket-receipt-card{background:white;border:1px solid var(--border-color);border-radius:12px;padding:36px;box-shadow:0 10px 30px rgba(0,0,0,.05)}.receipt-header{display:flex;justify-content:space-between;align-items:flex-start;gap:20px;border-bottom:1px solid var(--border-color);padding-bottom:24px}.status-badge{display:inline-block;font-size:.72rem;font-weight:700;border-radius:5px;padding:6px 10px}.badge-confirmed{background:#dcfce7;color:#15803d}.badge-concluded{background:#f1f5f9;color:#64748b}.receipt-meta-date,.item-label{color:var(--text-muted);font-size:.82rem}.ref-code{font-family:monospace;color:var(--primary);font-size:1rem}.receipt-section{padding:24px 0;border-bottom:1px solid var(--border-color)}.section-heading{color:var(--text-muted);font-size:.75rem;letter-spacing:.08em;margin-bottom:16px}.event-title{font-size:1.7rem;margin:0 0 20px}.receipt-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:22px}.receipt-grid>div{display:flex;flex-direction:column;gap:7px}.receipt-grid strong{font-size:.92rem;overflow-wrap:anywhere}.reason-text{line-height:1.8;color:var(--text-main);white-space:pre-line;background:#f8fafc;border-radius:6px;padding:15px}.attendee-grid{grid-template-columns:repeat(3,minmax(0,1fr))}.event-title{font-size:1.4rem}.receipt-footer{display:flex;justify-content:space-between;align-items:center;gap:16px;padding-top:24px;flex-wrap:wrap}.btn-primary{background:var(--primary);color:white;border:0;border-radius:8px;padding:12px 18px;cursor:pointer;font-weight:700}.btn-cancel-reg{border:0;background:none;color:#dc3545;text-decoration:underline;cursor:pointer}.concluded-notice{color:var(--text-muted);font-size:.83rem}.notice-card{text-align:center;padding:40px;background:#fff;border:1px solid var(--border-color);border-radius:12px}.notice-card p{color:var(--text-muted)}@media(max-width:650px){.ticket-receipt-card{padding:20px}.receipt-header{flex-direction:column}}</style>
